 dates.forEach((d,i)=>{const wd=new Date(d+'T12:00:00').getDay(),fill=(wd===0||wd===6)?[255,246,0]:[255,255,255];cell(margin+nameW+i*dateW,y,dateW,headerH,fill,rosterPdfDateLabel(d),{size:6.2,bold:true})});y+=headerH;
