async function verifyRosterAccess(event){event.preventDefault();const input=document.getElementById('rosterAccessCode'),status=document.getElementById('accessCodeStatus'),btn=document.getElementById('accessCodeSubmit'),code=input.value.trim();if(!code){status.textContent='Enter the access code.';status.className='access-code-status error';input.focus();return}btn.disabled=true;btn.textContent='Verifying...';status.textContent='Checking access code...';status.className='access-code-status';try{const response=await fetch(VERIFY_ACCESS_URL,{method:'POST',mode:'cors',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({app:'roster',code:code})});const raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch(_){data={message:raw}}const explicitlyDenied=data.valid===false||data.verified===false||data.authorized===false||data.success===false||data.allowed===false||data.ok===false||data.access===false||data.denied===true;if(!response.ok||explicitlyDenied){const serverMessage=data.message||data.error||data.detail||raw||'Access denied.';throw new Error('HTTP '+response.status+': '+serverMessage)};rosterAccessVerified=true;status.textContent='Access verified.';status.className='access-code-status success';input.value='';closeModal('accessCodeModal');setRosterEditMode(true)}catch(error){rosterAccessVerified=false;status.textContent=error.message||'Access verification failed. Please try again.';status.className='access-code-status error';input.select()}finally{btn.disabled=false;btn.textContent='Verify & Edit'}}
