async function saveRosterPaint(){if(!rosterPaint.active||rosterPaint.saving)return;const edits=[...rosterPaint.cells.values()],target=rosterPaint.targetState;rosterPaint.active=false;rosterPaint.saving=true;document.querySelector('#rosterManagementModal .roster-overview-modal')?.classList.remove('roster-painting');try{for(const date of new Set(edits.map(x=>x.date)))await ensureRosterDay(date);const rows=edits.map(x=>{const existing=overviewData.find(a=>a.roster_date===x.date&&a.member_id===x.member_id&&a.assignment_role==='crew');return {roster_date:x.date,member_id:x.member_id,team_no:x.team_no,assignment_role:'crew',is_present:target==='green',absence_reason:existing?.absence_reason||null,note:existing?.note||null,source:target==='green'?'inline':target==='red'?'inline_note_off':target==='beige'?'inline_beige':'inline_blank'}});for(let i=0;i<rows.length;i+=50)await rest('roster_assignments?on_conflict=roster_date,member_id,assignment_role',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(rows.slice(i,i+50))});await loadRosterOverview()}catch(e){alert('Roster update failed: '+e.message);await loadRosterOverview().catch(()=>{})}finally{rosterPaint.saving=false;resetRosterPaint()}}

function dutyCellClick(cell){if(!rosterEditMode)return;const date=cell.dataset.date,doMembers=DO_ORDER.map(n=>rosterMembers.find(m=>m.active&&m.role==='duty_officer'&&m.full_name===n)).filter(Boolean),select=document.createElement('select');select.className='do-choice';select.innerHTML='<option value="">Select DO</option>'+doMembers.map(m=>'<option value="'+m.id+'">'+esc(m.full_name)+'</option>').join('');const existing=overviewData.find(a=>a.roster_date===date&&a.assignment_role==='duty_officer');select.value=existing?.member_id||'';select.onclick=e=>e.stopPropagation();select.onchange=async()=>{select.disabled=true;try{await ensureRosterDay(date);await rest('roster_assignments?roster_date=eq.'+date+'&assignment_role=eq.duty_officer',{method:'DELETE',headers:{Prefer:'return=minimal'}});if(select.value)await rest('roster_assignments',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify([{roster_date:date,member_id:select.value,team_no:null,assignment_role:'duty_officer',is_present:true,source:'inline'}])});await loadRosterOverview()}catch(e){alert('Duty Officer update failed: '+e.message);select.disabled=false}};cell.innerHTML='';cell.appendChild(select);select.focus()}
async function editRosterCellText(event,cell){
 event.preventDefault();event.stopPropagation();
 if(!rosterEditMode||cell.querySelector('input,select'))return false;
 const date=cell.dataset.date,member=cell.dataset.member||cell.dataset.doMember;
 if(!date||!member)return false;
 let assignment=overviewData.find(a=>a.roster_date===date&&a.member_id===member);
 const wasOff=!assignment&&cell.classList.contains('crew-off');
 const original=assignment?.note||assignment?.absence_reason||cell.textContent.trim();
 const input=document.createElement('input');input.type='text';input.className='roster-text-editor';input.value=original;input.placeholder='Enter note';
 cell.classList.add('text-editing');cell.innerHTML='';cell.appendChild(input);input.focus();input.select();
 let finished=false;
 const finish=async save=>{if(finished)return;finished=true;const value=input.value.trim();if(!save){await loadRosterOverview();return}input.disabled=true;try{
   if(!assignment&&value){
     await ensureRosterDay(date);
     const created=await rest('roster_assignments',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify([{roster_date:date,member_id:member,team_no:cell.dataset.team?Number(cell.dataset.team):null,assignment_role:cell.dataset.member?'crew':'duty_officer',is_present:false,note:value,absence_reason:null,source:'inline_note_off'}])});
     assignment=created?.[0];
   }else if(assignment){
     const isOffNote=assignment.source==='inline_note_off';
     const isAbsence=!isOffNote&&/(^|\b)(leave|dil|adil|sick|sl|off|away|not worked|bereavement)(\b|$)/i.test(value);
     if(!value&&isOffNote){await rest('roster_assignments?id=eq.'+assignment.id,{method:'DELETE',headers:{Prefer:'return=minimal'}})}
     else await rest('roster_assignments?id=eq.'+assignment.id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({note:value||null,absence_reason:isAbsence?value:null,is_present:isOffNote?false:!isAbsence,source:isOffNote?'inline_note_off':assignment.source})});
   }
   await loadRosterOverview();
 }catch(e){alert('Note update failed: '+e.message);await loadRosterOverview()}};
 input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();finish(true)}else if(e.key==='Escape'){e.preventDefault();finish(false)}});
 input.addEventListener('blur',()=>setTimeout(()=>finish(true),0));
 return false;
}

