function resetMemberDrafts(){memberDrafts=new Map(rosterMembers.slice().sort((a,b)=>(a.display_order??9999)-(b.display_order??9999)||a.full_name.localeCompare(b.full_name)).map(m=>[m.id,{...m}]));memberDeletes=new Set();memberNewRows=[]}
function memberOrderButtons(i,total,id,isNew=false){return '<div class="member-order-controls"><button type="button" '+(i===0?'disabled':'')+' onclick="moveMemberRow('+(isNew?'true':'false')+','+i+',-1)">&#8593;</button><button type="button" '+(i===total-1?'disabled':'')+' onclick="moveMemberRow('+(isNew?'true':'false')+','+i+',1)">&#8595;</button></div>'}
function renderMembers(){const existing=[...memberDrafts.values()],total=existing.length+memberNewRows.length;document.getElementById('memberList').innerHTML=existing.map((m,i)=>'<div class="member-item editable '+(memberDeletes.has(m.id)?'pending-delete':'')+'">'+memberOrderButtons(i,total,m.id)+'<input value="'+esc(m.full_name)+'" onchange="stageMemberField(\''+m.id+'\',\'full_name\',this.value)"><select onchange="stageMemberField(\''+m.id+'\',\'role\',this.value)">'+memberRoleOptions(m.role)+'</select><select onchange="stageMemberTeam(\''+m.id+'\',this.value)">'+memberTeamOptions(m.default_team,m.member_group)+'</select><button class="button delete-member" onclick="toggleMemberDelete(\''+m.id+'\')">'+(memberDeletes.has(m.id)?'Undo':'Delete')+'</button></div>').join('')+memberNewRows.map((m,j)=>{const i=existing.length+j;return '<div class="member-item editable pending-new">'+memberOrderButtons(i,total,'',true)+'<input value="'+esc(m.full_name)+'" onchange="stageNewField('+j+',\'full_name\',this.value)"><select onchange="stageNewField('+j+',\'role\',this.value)">'+memberRoleOptions(m.role)+'</select><select onchange="stageNewTeam('+j+',this.value)">'+memberTeamOptions(m.default_team,m.member_group)+'</select><button class="button delete-member" onclick="removeNewMember('+j+')">Delete</button></div>'}).join('')}
function stageMemberField(id,f,v){const m=memberDrafts.get(id);m[f]=v}
function stageMemberTeam(id,v){const m=memberDrafts.get(id);m.member_group=v==='MS'?'ms':'crew';m.default_team=v&&v!=='MS'?Number(v):null}
function toggleMemberDelete(id){memberDeletes.has(id)?memberDeletes.delete(id):memberDeletes.add(id);renderMembers()}
function moveMemberRow(isNew,index,delta){const existing=[...memberDrafts.values()],all=existing.map(x=>({kind:'old',value:x})).concat(memberNewRows.map(x=>({kind:'new',value:x}))),to=index+delta;if(to<0||to>=all.length)return;[all[index],all[to]]=[all[to],all[index]];memberDrafts=new Map(all.filter(x=>x.kind==='old').map(x=>[x.value.id,x.value]));memberNewRows=all.filter(x=>x.kind==='new').map(x=>x.value);renderMembers()}
function stageNewMember(){const n=document.getElementById('newMemberName').value.trim();if(!n)return;const v=document.getElementById('newMemberTeam').value;memberNewRows.push({full_name:n,role:document.getElementById('newMemberRole').value,default_team:v&&v!=='MS'?Number(v):null,member_group:v==='MS'?'ms':'crew',active:true});document.getElementById('newMemberName').value='';renderMembers()}
function stageNewField(i,f,v){memberNewRows[i][f]=v}
function stageNewTeam(i,v){memberNewRows[i].member_group=v==='MS'?'ms':'crew';memberNewRows[i].default_team=v&&v!=='MS'?Number(v):null}
function removeNewMember(i){memberNewRows.splice(i,1);renderMembers()}
async function saveMemberChanges(){const x=document.getElementById('memberSaveState');x.textContent='Saving...';try{for(const id of memberDeletes){await rest('roster_assignments?member_id=eq.'+id,{method:'DELETE',headers:{Prefer:'return=minimal'}});await rest('roster_members?id=eq.'+id,{method:'DELETE',headers:{Prefer:'return=minimal'}})}const existing=[...memberDrafts.values()].filter(m=>!memberDeletes.has(m.id));for(let i=0;i<existing.length;i++){const m=existing[i];await rest('roster_members?id=eq.'+m.id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({full_name:m.full_name.trim(),role:m.role,default_team:m.default_team,member_group:m.member_group||'crew',display_order:i})})}if(memberNewRows.length){const offset=existing.length;await rest('roster_members',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(memberNewRows.map((m,i)=>({...m,display_order:offset+i})))})}await loadMembers();closeModal('dailyRosterModal');openModal('rosterManagementModal');await loadRosterOverview()}catch(e){x.textContent='Save failed: '+e.message}}
async function closeMembersWithoutSaving(){resetMemberDrafts();closeModal('dailyRosterModal');openModal('rosterManagementModal');await loadRosterOverview()}

function addISO(d,n){const x=new Date(d+'T00:00:00Z');x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)}
async function copyRosterPattern(){const state=document.getElementById('rosterSaveState'),count=Number(document.getElementById('teamCount').value);state.textContent='Generating 6 months...';try{const last=(await rest('roster_days?select=roster_date&order=roster_date.desc&limit=1'))[0]?.roster_date||document.getElementById('rosterEditDate').value;const total=183,memberByName=Object.fromEntries(rosterMembers.map(m=>[m.full_name.toLowerCase(),m]));let source=[];
 if(count===3){source=await rest('roster_pattern?select=*&order=pattern_day,team_no');}else{const from=addISO(last,-27);source=await rest('roster_assignments?roster_date=gte.'+from+'&roster_date=lte.'+last+'&select=*,roster_members(full_name)&order=roster_date');}
 const days=[],out=[];for(let i=1;i<=total;i++){const target=addISO(last,i);days.push({roster_date:target,day_note:null,source:'pattern'});if(count===3){const max=Math.max(...source.map(x=>x.pattern_day),0)+1;for(const p of source.filter(x=>x.pattern_day===((i-1)%max))){const m=memberByName[p.member_name.toLowerCase()];if(m)out.push({roster_date:target,member_id:m.id,team_no:p.team_no,assignment_role:p.assignment_role,is_present:p.is_present,note:p.note,source:'pattern'})}}else{const srcDate=addISO(last,-27+((i-1)%28));for(const a of source.filter(x=>x.roster_date===srcDate))out.push({roster_date:target,member_id:a.member_id,team_no:a.team_no,assignment_role:a.assignment_role,is_present:a.is_present,absence_reason:a.absence_reason,note:a.note,source:'pattern'})}}
 await rest('roster_days?on_conflict=roster_date',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify(days)});for(let i=0;i<out.length;i+=500)await rest('roster_assignments?on_conflict=roster_date,member_id,assignment_role',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify(out.slice(i,i+500))});state.textContent='Created through '+addISO(last,total)+' ('+out.length+' assignments).';}catch(e){state.textContent='Pattern failed: '+e.message}}

