let hourlyCache=null,hourlyCacheAt=0;
async function getHourly(){
 if(hourlyCache&&Date.now()-hourlyCacheAt<600000)return hourlyCache;
 const wxUrl='https://api.open-meteo.com/v1/forecast?latitude='+HARBOUR_LAT+'&longitude='+HARBOUR_LON+'&hourly=temperature_2m,apparent_temperature,precipitation,precipitation_probability,weather_code,wind_speed_10m,wind_gusts_10m,wind_direction_10m&daily=sunrise,sunset,temperature_2m_max,temperature_2m_min,weather_code&wind_speed_unit=kn&timezone=Pacific%2FAuckland&forecast_days=3';
 const res=await fetch(wxUrl);
 hourlyCache={wx:res.ok?await res.json():null};
 hourlyCacheAt=Date.now();return hourlyCache;
}
function nowHourIndex(times){const now=new Date();let best=0,diff=Infinity;for(let i=0;i<times.length;i++){const d=Math.abs(new Date(times[i])-now);if(d<diff){diff=d;best=i}}return best}
function fcHM(iso){try{return new Intl.DateTimeFormat('en-NZ',{timeZone:'Pacific/Auckland',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(iso))}catch(_){return '--'}}
function fcDay(iso){try{return new Intl.DateTimeFormat('en-NZ',{timeZone:'Pacific/Auckland',weekday:'short'}).format(new Date(iso))}catch(_){return ''}}
// SVG sparkline
function sparkline(values,opts={}){
 const {w=620,h=132,color='#2086c7',fill='rgba(32,134,199,.14)',unit='',markers=[]}=opts;
 const idx=values.map((v,i)=>[v,i]).filter(p=>p[0]!=null&&isFinite(p[0]));
 if(!idx.length)return '<div class="fc-empty">No data available</div>';
 const vals=idx.map(p=>p[0]);let mn=Math.min(...vals),mx=Math.max(...vals);if(mn===mx){mn-=1;mx+=1}
 const padX=12,padTop=14,padBot=26,n=values.length;
 const x=i=>padX+(n<=1?0:(i/(n-1))*(w-padX*2)),y=v=>padTop+(mx-v)/(mx-mn)*(h-padTop-padBot);
 let d='';idx.forEach((p,k)=>{d+=(k?'L':'M')+x(p[1]).toFixed(1)+' '+y(p[0]).toFixed(1)+' '});
 const area=d+'L '+x(idx[idx.length-1][1]).toFixed(1)+' '+(h-padBot)+' L '+x(idx[0][1]).toFixed(1)+' '+(h-padBot)+' Z';
 let g='';for(let k=0;k<4;k++){const yy=padTop+k*(h-padTop-padBot)/3,val=mx-(k*(mx-mn)/3);g+='<line x1="'+padX+'" y1="'+yy.toFixed(1)+'" x2="'+(w-padX)+'" y2="'+yy.toFixed(1)+'" stroke="#eef3f7"/><text x="'+padX+'" y="'+(yy-3).toFixed(1)+'" font-size="9" fill="#9aabb8">'+(Math.round(val*10)/10)+unit+'</text>'}
 let mk='';markers.forEach(mkr=>{const xx=x(mkr.i);mk+='<line x1="'+xx.toFixed(1)+'" y1="'+padTop+'" x2="'+xx.toFixed(1)+'" y2="'+(h-padBot)+'" stroke="'+(mkr.color||'#ef3124')+'" stroke-dasharray="4 4"/><text x="'+Math.min(xx+3,w-40).toFixed(1)+'" y="'+(padTop+9)+'" font-size="9" fill="'+(mkr.color||'#ef3124')+'" font-weight="700">'+(mkr.label||'')+'</text>'});
 let lb='';for(let i=0;i<n;i+=Math.max(1,Math.round(n/6))){if(values[i]==null)continue;lb+='<text x="'+x(i).toFixed(1)+'" y="'+(h-8)+'" font-size="9" fill="#7f97a6" text-anchor="middle">'+fcHM(opts.times?opts.times[i]:'')+'</text>'}
 return '<svg class="fc-spark" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none"><defs><linearGradient id="fcg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="'+color+'" stop-opacity=".28"/><stop offset="1" stop-color="'+color+'" stop-opacity="0"/></linearGradient></defs>'+g+'<path d="'+area+'" fill="url(#fcg)"/><path d="'+d+'" fill="none" stroke="'+color+'" stroke-width="2.5"/>'+mk+lb+'</svg>';
}
function fcSlice(data,startIdx,count,step){const out=[];for(let i=startIdx;i<data.times.length&&out.length<count;i+=step)out.push(i);return out}
async function openForecast(type){
 const body=document.getElementById('forecastBody'),title=document.getElementById('forecastTitle'),sub=document.getElementById('forecastSubtitle');
 title.textContent='Loading\u2026';sub.textContent='Auckland Harbour';body.innerHTML='<div class="fc-empty">Loading forecast\u2026</div>';openModal('forecastModal');
 try{
  if(type==='tide'){return renderTideForecast(body,title,sub)}
  const H=await getHourly();
  if(type==='weather')return renderWeatherForecast(body,title,sub,H);
  if(type==='wind')return renderWindForecast(body,title,sub,H);
  if(type==='sun')return renderSunForecast(body,title,sub,H);
 }catch(e){body.innerHTML='<div class="fc-empty">Forecast unavailable.<br>'+esc(e.message||e)+'</div>'}
}
function renderWeatherForecast(body,title,sub,H){
 title.textContent='Weather Forecast';sub.textContent='Auckland Harbour \u00b7 next 24 hours';
 const hw=H.wx&&H.wx.hourly;if(!hw)return void(body.innerHTML='<div class="fc-empty">Weather feed unavailable.</div>');
 const t=hw.time,ni=nowHourIndex(t),temps=hw.temperature_2m,spark=sparkline(temps.slice(ni,ni+24),{times:t.slice(ni,ni+24),unit:'\u00b0',color:'#2086c7',markers:[{i:0,label:'Now',color:'#ef3124'}]});
 const idxs=fcSlice({times:t},ni,10,3);let rows='';idxs.forEach(i=>{const[desc,ico]=WX_CODE[hw.weather_code[i]]||['',''];rows+='<tr'+(i===ni?' class="now-row"':'')+'><td>'+(i===ni?'Now':fcHM(t[i]))+'</td><td>'+ico+' '+Math.round(hw.temperature_2m[i])+'\u00b0</td><td>'+Math.round(hw.apparent_temperature[i])+'\u00b0</td><td>'+(hw.precipitation_probability[i]??'--')+'%</td><td>'+desc+'</td></tr>'});
 body.innerHTML='<div class="fc-hero"><div class="fc-hero-ico">'+((WX_CODE[hw.weather_code[ni]]||['',''])[1])+'</div><div class="fc-hero-main"><div class="fc-hero-val">'+Math.round(temps[ni])+'\u00b0C</div><div class="fc-hero-sub">Feels '+Math.round(hw.apparent_temperature[ni])+'\u00b0 \u00b7 '+((WX_CODE[hw.weather_code[ni]]||['',''])[0])+'</div></div></div><div class="fc-spark-wrap"><div class="fc-spark-title">Temperature <span>next 24h</span></div>'+spark+'</div><div class="fc-table-wrap"><table class="fc-table"><thead><tr><th>Time</th><th>Temp</th><th>Feels</th><th>Rain</th><th>Sky</th></tr></thead><tbody>'+rows+'</tbody></table></div>';
}
function renderWindForecast(body,title,sub,H){
 title.textContent='Wind Forecast';sub.textContent='Auckland Harbour \u00b7 next 24 hours';
 const hw=H.wx&&H.wx.hourly;if(!hw)return void(body.innerHTML='<div class="fc-empty">Wind feed unavailable.</div>');
 const t=hw.time,ni=nowHourIndex(t),spark=sparkline(hw.wind_speed_10m.slice(ni,ni+24),{times:t.slice(ni,ni+24),unit:'kt',color:'#0e7f74',markers:[{i:0,label:'Now',color:'#ef3124'}]});
 const idxs=fcSlice({times:t},ni,10,3);let rows='';idxs.forEach(i=>{rows+='<tr'+(i===ni?' class="now-row"':'')+'><td>'+(i===ni?'Now':fcHM(t[i]))+'</td><td>'+Math.round(hw.wind_speed_10m[i])+' kt</td><td>'+Math.round(hw.wind_gusts_10m[i])+' kt</td><td>'+compass(hw.wind_direction_10m[i])+' ('+Math.round(hw.wind_direction_10m[i])+'\u00b0)</td></tr>'});
 body.innerHTML='<div class="fc-hero"><div class="fc-hero-ico">\ud83d\udca8</div><div class="fc-hero-main"><div class="fc-hero-val">'+Math.round(hw.wind_speed_10m[ni])+' kt</div><div class="fc-hero-sub">'+compass(hw.wind_direction_10m[ni])+' \u00b7 gusting '+Math.round(hw.wind_gusts_10m[ni])+' kt</div></div></div><div class="fc-spark-wrap"><div class="fc-spark-title">Wind speed <span>next 24h</span></div>'+spark+'</div><div class="fc-table-wrap"><table class="fc-table"><thead><tr><th>Time</th><th>Wind</th><th>Gust</th><th>Direction</th></tr></thead><tbody>'+rows+'</tbody></table></div>';
}
function renderSunForecast(body,title,sub,H){
 title.textContent='Sun & Daylight';sub.textContent='Auckland Harbour \u00b7 3-day';
 const d=H.wx&&H.wx.daily;if(!d)return void(body.innerHTML='<div class="fc-empty">Sun data unavailable.</div>');
 let rows='';for(let i=0;i<(d.time?d.time.length:0);i++){const mins=Math.round((new Date(d.sunset[i])-new Date(d.sunrise[i]))/60000);rows+='<tr'+(i===0?' class="now-row"':'')+'><td>'+(i===0?'Today':fcDay(d.time[i]))+'</td><td>\u2191 '+fcHM(d.sunrise[i])+'</td><td>\u2193 '+fcHM(d.sunset[i])+'</td><td>'+Math.floor(mins/60)+'h '+(mins%60)+'m</td></tr>'}
 const mins0=Math.round((new Date(d.sunset[0])-new Date(d.sunrise[0]))/60000);
 body.innerHTML='<div class="fc-hero"><div class="fc-hero-ico">\u2600\ufe0f</div><div class="fc-hero-main"><div class="fc-hero-val">'+fcHM(d.sunrise[0])+' \u2013 '+fcHM(d.sunset[0])+'</div><div class="fc-hero-sub">'+Math.floor(mins0/60)+'h '+(mins0%60)+'m of daylight today</div></div></div><div class="fc-table-wrap"><table class="fc-table"><thead><tr><th>Day</th><th>Sunrise</th><th>Sunset</th><th>Daylight</th></tr></thead><tbody>'+rows+'</tbody></table></div>';
}
async function renderTideForecast(body,title,sub){
 title.textContent='Auckland Tide';sub.textContent='Today \u00b7 high & low water';
 try{const file='Auckland '+nzYear()+'.csv',events=normalizeRows(parseCSV(await fetchFile(file)),file),today=nzDate(),nowM=nzMin();
  const dayPts=events.filter(e=>e.iso===today).sort((a,b)=>a.min-b.min);if(!dayPts.length)return void(body.innerHTML='<div class="fc-empty">No tide record for today.</div>');
  const next=dayPts.find(p=>p.min>=nowM)||dayPts[0];let rows='';dayPts.forEach(p=>{const isNext=p===next;rows+='<tr'+(isNext?' class="now-row"':'')+'><td>'+fmtTime(p.min)+'</td><td>'+(p.type==='HW'?'\ud83c\udf0a High':'\ud83c\udfd6\ufe0f Low')+'</td><td>'+fmtH(p.height)+'</td></tr>'});
  const low=dayPts.reduce((a,b)=>a.height<b.height?a:b),high=dayPts.reduce((a,b)=>a.height>b.height?a:b);
  body.innerHTML='<div class="fc-hero"><div class="fc-hero-ico">'+(next.type==='HW'?'\ud83c\udf0a':'\ud83c\udfd6\ufe0f')+'</div><div class="fc-hero-main"><div class="fc-hero-val">'+(next.type==='HW'?'High ':'Low ')+fmtTime(next.min)+'</div><div class="fc-hero-sub">'+fmtH(next.height)+' \u00b7 next tide</div></div></div><div class="fc-stat-grid"><div class="fc-stat"><strong>Highest today</strong><div class="v">'+fmtTime(high.min)+' \u00b7 '+fmtH(high.height)+'</div></div><div class="fc-stat"><strong>Lowest today</strong><div class="v">'+fmtTime(low.min)+' \u00b7 '+fmtH(low.height)+'</div></div></div><div class="fc-table-wrap"><table class="fc-table"><thead><tr><th>Time</th><th>Tide</th><th>Height</th></tr></thead><tbody>'+rows+'</tbody></table></div><p class="fc-note">Source: Supabase <b>tide-data</b>. Open the Tide panel below for the full graph and other locations.</p>';
 }catch(e){body.innerHTML='<div class="fc-empty">Tide data unavailable.<br>'+esc(e.message||e)+'</div>'}
}

