let contactRows=[],contactEditing=false,contactSnapshot='',selectedPhone='',selectedContactCell=null;
function inferContactType(c){const n=c.filter(Boolean);if(n.length===1&&CONTACT_SECTIONS.has(n[0].trim()))return'section';if(n.some(v=>/^(Harbourmaster - Team|DDI\s+Email|Mobile)$/i.test(v.trim())))return'subheader';return'normal'}
function safeStyleData(v){if(!v)return{row:{},cells:[{},{},{}]};if(typeof v==='string'){try{v=JSON.parse(v)}catch(_){v={}}}return{row:v.row||{},cells:[v.cells?.[0]||{},v.cells?.[1]||{},v.cells?.[2]||{}]}}
function mapContact(r){return{id:r.id||null,cells:[r.column_1||'',r.column_2||'',r.column_3||''],row_type:r.row_type||'normal',display_order:+r.display_order||0,updated_at:r.updated_at,style_data:safeStyleData(r.style_data)}}
async function fetchContacts(){return rest('contact_list?select=id,display_order,column_1,column_2,column_3,row_type,is_active,updated_at,style_data&is_active=eq.true&order=display_order.asc,id.asc')}
async function seedContacts(){await rest('contact_list',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(CONTACT_DEFAULT_ROWS.map((c,i)=>({display_order:(i+1)*10,column_1:c[0],column_2:c[1],column_3:c[2],row_type:inferContactType(c),is_active:true,style_data:{row:{},cells:[{},{},{}]}})))})}
function updateLabel(v){document.getElementById('contactUpdated').textContent=v?new Intl.DateTimeFormat('en-NZ',{timeZone:'Pacific/Auckland',weekday:'short',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZoneName:'short'}).format(new Date(v)):'Not yet saved'}
async function loadContacts(){let r=await fetchContacts();if(!r.length){await seedContacts();r=await fetchContacts()}contactRows=r.map(mapContact);updateLabel(contactRows.map(x=>x.updated_at).filter(Boolean).sort().at(-1))}
function linkifyContact(text){const escaped=esc(text);const token=/(https?:\/\/[^\s<]+|(?:www\.)?[a-z0-9-]+\.(?:com|co\.nz|govt\.nz|nz)(?:\/[^\s<]*)?|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}|(?:\+?64[\s-]?)?(?:0\d|\d{2})[\d\s-]{5,}\d)/gi;return escaped.replace(token,m=>{if(m.includes('@'))return'<a href="mailto:'+m+'">'+m+'</a>';if(/^(?:https?:\/\/|www\.)/i.test(m)||/\.(?:com|co\.nz|govt\.nz|nz)(?:\/|$)/i.test(m)){const h=/^https?:/i.test(m)?m:'https://'+m;return'<a href="'+h+'" target="_blank" rel="noopener noreferrer">'+m+'</a>'}if(m.replace(/\D/g,'').length>=7)return'<a href="#" class="phone-link" data-phone="'+m+'" onclick="choosePhoneCall(event,this.dataset.phone)">'+m+'</a>';return m}).replace(/\n/g,'<br>')}
function cssStyle(obj){return Object.entries(obj||{}).filter(([,v])=>v).map(([k,v])=>k.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())+':'+v).join(';')}
function renderContacts(){selectedContactCell=null;document.getElementById('contactTableBody').innerHTML=contactRows.map((r,i)=>{const bg=r.style_data?.row?.backgroundColor||'';return'<tr class="'+(r.row_type==='section'?'section-row':r.row_type==='subheader'?'subhead-row':'')+'" data-row="'+i+'">'+r.cells.map((c,j)=>{const style=cssStyle(r.style_data?.cells?.[j]);const bgVar=bg?'--contact-row-bg:'+bg+';background-color:'+bg+';':'';const actions=contactEditing&&j===0?'<span class="contact-row-actions"><button class="contact-row-action" type="button" onclick="moveContactRow(event,'+i+',-1)" title="Move row up">↑</button><button class="contact-row-action" type="button" onclick="moveContactRow(event,'+i+',1)" title="Move row down">↓</button><button class="contact-row-action delete" type="button" onclick="deleteContactRow(event,'+i+')" title="Delete row">×</button></span>':'';const content=contactEditing?'<div class="contact-cell-editor" contenteditable="true" data-row="'+i+'" data-col="'+j+'" onfocus="selectContactCell(this.parentElement)" onclick="selectContactCell(this.parentElement)">'+esc(c).replace(/\n/g,'<br>')+'</div>':linkifyContact(c);return'<td data-row="'+i+'" data-col="'+j+'" style="'+bgVar+style+'" onclick="selectContactCell(this)">'+actions+content+'</td>'}).join('')+'</tr>'}).join('')}
async function openContactList(){openModal('contactListModal');document.getElementById('contactTableBody').innerHTML='<tr><td colspan="3">Loading shared Contact List...</td></tr>';try{await loadContacts();renderContacts();syncContactMode()}catch(e){document.getElementById('contactStatus').textContent='Load failed: '+e.message}}
function syncContactMode(){document.getElementById('contactListPanel').classList.toggle('editing',contactEditing);const saveBtn=document.getElementById('contactSaveBtn'),editBtn=document.getElementById('contactEditBtn');saveBtn.hidden=!contactEditing;saveBtn.style.display=contactEditing?'inline-flex':'none';editBtn.hidden=contactEditing;editBtn.style.display=contactEditing?'none':'inline-flex';document.getElementById('contactHint').textContent=contactEditing?'Select a cell to format it. Use ↑ and ↓ to reorder rows, then Save.':'Shared Supabase list. Emails, websites and phone numbers are clickable.'}
function collectContacts(){return[...document.querySelectorAll('#contactTableBody tr')].map((tr,i)=>{const c=[...tr.querySelectorAll('td')].map(td=>{const editor=td.querySelector('.contact-cell-editor');return(editor?editor.innerText:td.innerText).replace(/\n{3,}/g,'\n\n').trim()});const old=contactRows[Number(tr.dataset.row)]||contactRows[i]||{};return{id:old.id||null,cells:c,row_type:old.row_type||inferContactType(c),display_order:(i+1)*10,style_data:safeStyleData(old.style_data)}})}
function selectContactCell(td){if(!contactEditing||!td)return;document.querySelectorAll('.contact-cell-selected').forEach(x=>x.classList.remove('contact-cell-selected'));selectedContactCell=td;td.classList.add('contact-cell-selected');const r=contactRows[+td.dataset.row],st=r?.style_data?.cells?.[+td.dataset.col]||{};document.getElementById('contactFontSize').value=st.fontSize||'';document.getElementById('contactTextColor').value=st.color||'#102536';document.getElementById('contactRowColor').value=r?.style_data?.row?.backgroundColor||'#ffffff';document.getElementById('contactBoldBtn').classList.toggle('active',st.fontWeight==='700'||st.fontWeight==='bold')}
function captureContactText(){if(contactEditing)contactRows=collectContacts()}
function applyContactCellStyle(prop,value){if(!selectedContactCell)return;const ri=+selectedContactCell.dataset.row,ci=+selectedContactCell.dataset.col;captureContactText();contactRows[ri].style_data=safeStyleData(contactRows[ri].style_data);if(value)contactRows[ri].style_data.cells[ci][prop]=value;else delete contactRows[ri].style_data.cells[ci][prop];renderContacts();selectContactCell(document.querySelector('td[data-row="'+ri+'"][data-col="'+ci+'"]'))}
function toggleContactBold(){if(!selectedContactCell)return;const ri=+selectedContactCell.dataset.row,ci=+selectedContactCell.dataset.col,st=contactRows[ri].style_data.cells[ci]||{};applyContactCellStyle('fontWeight',(st.fontWeight==='700'||st.fontWeight==='bold')?'':'700')}
function applyContactRowBackground(value){if(!selectedContactCell)return;const ri=+selectedContactCell.dataset.row,ci=+selectedContactCell.dataset.col;captureContactText();contactRows[ri].style_data=safeStyleData(contactRows[ri].style_data);contactRows[ri].style_data.row.backgroundColor=value;renderContacts();selectContactCell(document.querySelector('td[data-row="'+ri+'"][data-col="'+ci+'"]'))}
function clearContactFormatting(){if(!selectedContactCell)return;const ri=+selectedContactCell.dataset.row,ci=+selectedContactCell.dataset.col;captureContactText();contactRows[ri].style_data.cells[ci]={};renderContacts();selectContactCell(document.querySelector('td[data-row="'+ri+'"][data-col="'+ci+'"]'))}
function moveContactRow(event,i,delta){event.preventDefault();event.stopPropagation();captureContactText();const to=i+delta;if(to<0||to>=contactRows.length)return;[contactRows[i],contactRows[to]]=[contactRows[to],contactRows[i]];contactRows.forEach((r,n)=>r.display_order=(n+1)*10);renderContacts()}
function addContactRow(){captureContactText();contactRows.push({id:null,cells:['','',''],row_type:'normal',display_order:(contactRows.length+1)*10,style_data:safeStyleData(null)});renderContacts();const editor=document.querySelector('#contactTableBody tr:last-child td:first-child .contact-cell-editor');editor?.focus()}
