async function saveContactList(){captureContactText();const b=document.getElementById('contactSaveBtn'),st=document.getElementById('contactStatus');b.disabled=true;st.textContent='Saving...';try{const old=await fetchContacts(),keep=contactRows.filter(r=>r.id).map(r=>r.id),del=old.filter(r=>!keep.includes(r.id)).map(r=>r.id);if(del.length)await rest('contact_list?id=in.('+del.join(',')+')',{method:'DELETE',headers:{Prefer:'return=minimal'}});for(const r of contactRows.filter(r=>r.id))await rest('contact_list?id=eq.'+r.id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({display_order:r.display_order,column_1:r.cells[0],column_2:r.cells[1],column_3:r.cells[2],row_type:r.row_type,is_active:true,style_data:r.style_data})});const add=contactRows.filter(r=>!r.id).map(r=>({display_order:r.display_order,column_1:r.cells[0],column_2:r.cells[1],column_3:r.cells[2],row_type:r.row_type,is_active:true,style_data:r.style_data}));if(add.length)await rest('contact_list',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(add)});await loadContacts();contactEditing=false;syncContactMode();renderContacts();st.textContent='Saved to Supabase'}catch(e){st.textContent='Save failed: '+e.message}finally{b.disabled=false}}
